export default class GlyphIterator{constructor(t,e){this.glyphs=t,this.reset(e)}reset(t={},e=0){this.options=t,this.flags=t.flags||{},this.markAttachmentType=t.markAttachmentType||0,this.index=e}get cur(){return this.glyphs[this.index]||null}shouldIgnore(t){return this.flags.ignoreMarks&&t.isMark||this.flags.ignoreBaseGlyphs&&t.isBase||this.flags.ignoreLigatures&&t.isLigature||this.markAttachmentType&&t.isMark&&t.markAttachmentType!==this.markAttachmentType}move(t){for(this.index+=t;0<=this.index&&this.index<this.glyphs.length&&this.shouldIgnore(this.glyphs[this.index]);)this.index+=t;return 0>this.index||this.index>=this.glyphs.length?null:this.glyphs[this.index]}next(){return this.move(1)}prev(){return this.move(-1)}peek(t=1){let e=this.index,s=this.increment(t);return this.index=e,s}peekIndex(t=1){let e=this.index;this.increment(t);let s=this.index;return this.index=e,s}increment(t=1){let e=t<0?-1:1;for(t=Math.abs(t);t--;)this.move(e);return this.glyphs[this.index]}}